Q: How to throttle events in bloc? A: <blockquote>
<blockquote>
<p>I want to trigger file save on user input, but perform file system access not more often than once per 100ms?</p>
</blockquote>
</blockquote>
<p>Throttling method: <code>bucket.allowRequest()</code><br />
Throttled method: <code>handler()</code></p>
<pre class="lang-dart prettyprint-override"><code>import 'dart:async';

import 'package:multitasking/misc/speed_meter.dart';
import 'package:multitasking/misc/token_bucket.dart';

void main() {
  // Limit to 10 times per second (1000 ms / 100 ms)
  const rate = 1000 / 100;
  final bucket = TokenBucket(capacity: 1 / rate, rate: rate);
  final meter = SpeedMeter.run();

  void handler(String object) {
    final seconds = (meter.elapsedMicroseconds / 1e6).toStringAsFixed(2);
    print('$seconds: $object');
  }

  var stop = false;

  Timer.periodic(Duration(milliseconds: 1000), (timer) {
    final speed = meter.speed;
    final rate = speed.toStringAsFixed(2);
    final interval = (speed == 0 ? 0.0 : 1 / speed).toStringAsFixed(2);
    print('speed: $rate times/sec ($interval ms)');
    if (timer.tick == 3) {
      stop = true;
      timer.cancel();
    }
  });

  Timer.periodic(Duration(milliseconds: 10), (timer) {
    // Throttling method: `bucket.allowRequest()`
    if (bucket.allowRequest()) {
      meter.add(1);
      // Throttled method: `handler()`
      handler('Tick ${timer.tick}');
      if (stop) {
        timer.cancel();
      }
    }
  });
}

</code></pre>
